/* Animal (and other) friends for worlds 23–28 */
Object.assign(COMPS,{
  spark:{name:'Angel Spark',e:'✨',type:'heal',p:10,desc:'A tiny spark of heaven\'s light that warms you back to health. Jacob saw angels on the stairway (Genesis 28:12).'},
  lamp:{name:'Temple Lamp',e:'🪔',type:'shield',p:44,desc:'"The lamp of God had not yet gone out" (1 Samuel 3:3). Its glow softens the next hit.'},
  monkey:{name:'Ship Monkey',e:'🐒',type:'coins',p:9,desc:'Came home on Solomon\'s ships with gold and silver (1 Kings 10:22). Brings extra shekels after each win.'},
  swan:{name:'River Swan',e:'🦢',type:'all',p:9,desc:'Glides along the Jordan and splashes every foe at once.'},
  jar:{name:'Water Jar',e:'🏺',type:'heal',p:13,desc:'Filled to the brim, like the jars at Cana (John 2:7). Refreshes you every turn.'},
  squirrel:{name:'Fig Squirrel',e:'🐿️',type:'attack',p:17,desc:'Quick and brave, from a fig tree in Bethany. Jumps in to help every turn.'}
});

/* Battle mechanic texts, cutscene banners and treasures */
Object.assign(STR.en,{
 'bm.restless':'Jacob could not rest. Answer 4 right to climb the stairway, and a blast of heaven\'s light hits the gloom!','bm.restless.m':'Climb the stairway','bm.restless.full':'Up the stairway! "I am with you!" Heaven\'s light blasts the gloom!',
 'bm.sleepy':'The sleepy fog keeps growing back! Answer 3 right to light the lamp of God and stop it.','bm.sleepy.m':'Light the lamp','bm.sleepy.full':'"Speak, LORD, for your servant hears!" The lamp shines, and the fog stops growing back.',
 'bm.riddle':'The gloom hides behind a shield of riddles. Answer right in 3 different subjects to break it. True wisdom comes from God!','bm.riddle.m':'Wisdom','bm.riddle.full':'Wisdom from God breaks the riddle shield!',
 'bm.tempter':'Answer like Jesus did: "It is written!" Bible and memory-verse answers hit hard. Other answers only hit weakly.','bm.tempter.m':'It is written!','bm.tempter.full':'"It is written!" God\'s word drives the tempter away!',
 'bm.empty':'The six stone jars are empty. Every right answer fills one jar. When all six are full, your attacks are strong!','bm.empty.m':'Jars filled','bm.empty.one':'Jar filled!','bm.empty.full':'All six jars are filled to the brim! Your attacks are strong now!',
 'bm.grief':'A heavy stone blocks the tomb. Every 3 right answers, roll it away with a big blast!','bm.grief.m':'Roll away the stone','bm.grief.full':'"Lazarus, come out!" The stone rolls away!',
 'furn.stonepillar':'Jacob\'s stone pillar','furn.templelamp':'The lamp of God','furn.goldenlamp':'Golden temple lamp','furn.rivershell':'Shell from the Jordan','furn.stonejar':'Stone water jar from Cana','furn.perfumejar':'Mary\'s jar of perfume',
 'cut.23':'God is with you wherever you go!','cut.24':'Speak, Lord, I am listening!','cut.25':'Wisdom comes from God!','cut.26':'This is my beloved Son!','cut.27':'The best wine was saved for last!','cut.28':'Jesus is the resurrection and the life!'
});

/* ---------- German ---------- */
Object.assign(DE.CH,{
23:{name:'Bethel',book:'1. Mose 28',foe:{name:'Bangling',pl:'Banglinge',what:'Schatten der Einsamkeit'},foes:[{name:'Bangling'},{name:'Einsamkeitslicht'},{name:'Nachttropfen'}],
 boss:{name:'Ruheloses Dunkel',where:'beim Steinmal'},guide:{name:'Jakob'},
 intro:['Psst ... es ist Nacht. Ich bin Jakob. Ich bin von zu Hause weggelaufen, weil mein Bruder Esau sehr wütend auf mich ist.','Ich habe ihn ausgetrickst und mir den Segen geholt, der für ihn bestimmt war. Jetzt gehe ich weit weg, zu meinem Onkel Laban nach Haran.','Die Sonne ist untergegangen, also habe ich einen von diesen Steinen als Kopfkissen genommen. Ich habe mich noch nie so allein gefühlt. Sieht Gott mich hier draußen überhaupt?','Banglinge flüstern ständig: „Du bist ganz allein. Niemand ist bei dir.“ Besiege 5 Düsterlinge, dann stell dich dem Ruhelosen Dunkel beim Steinmal.'],
 hint:'Das Ruhelose Dunkel wartet beim Steinmal. Du bist nie zu weit weg, als dass Gott dich nicht finden könnte!',
 outro:['Ich hatte einen Traum! Eine Treppe stand auf der Erde, und ihre Spitze reichte bis zum Himmel. Gottes Engel stiegen darauf hinauf und herab!','Der Herr stand oben und sagte: „Ich bin mit dir und will dich behüten, wohin du auch gehst.“ Ich wachte auf und sagte: „Wirklich, der Herr ist an diesem Ort, und ich wusste es nicht!“','Ich habe mein Steinkissen als Steinmal aufgestellt, Öl darauf gegossen und den Ort Bethel genannt, „Haus Gottes“. Hier ist ein Teil der Schriftrolle. Und dieser kleine Engelsfunke möchte mit dir kommen und dir den Weg leuchten!'],
 post:'Auch wenn du dich allein fühlst: Gott ist bei dir, wohin du auch gehst.',
 side:{name:'Hirte aus Lus',what:'verlorene Lämmer',ask:'Die Stadt da drüben heißt Lus. Ich bin Hirte, und 3 meiner Lämmer sind im Dunkeln weggelaufen! Findest du sie?',thanks:'Du hast sie alle gefunden! Gott passt auf Jakob noch besser auf als ich auf meine Lämmer. Nimm das.'},
 flav:[{name:'Reisender',lines:['Dieser junge Mann geht den ganzen Weg von Beerscheba bis nach Haran. Das ist ein sehr langer Weg, wenn man allein ist!']},{name:'Alte Frau aus Lus',lines:['Vor langer Zeit hat Jakobs Großvater Abraham hier in der Nähe einen Altar gebaut und den Namen des Herrn angerufen.']}],
 verse:{t:'Ich bin mit dir und will dich behüten, wohin du auch gehst.',r:'1. Mose 28,15'}},
24:{name:'Silo',book:'1. Samuel 1–3',foe:{name:'Döserling',pl:'Döserlinge',what:'Schatten des Nicht-Zuhörens'},foes:[{name:'Döserling'},{name:'Gähnlicht'},{name:'Schnarchgroll'}],
 boss:{name:'Der Schlafnebel',where:'beim Haus des Herrn'},guide:{name:'Samuel'},
 intro:['Hallo! Ich bin Samuel. Ich wohne hier in Silo, beim Haus des Herrn, und helfe dem Priester Eli.','Meine Mutter Hanna hat lange, lange um ein Baby gebetet. Gott hat ihr Gebet erhört, und das bin ich! Darum hat sie mich hierher gebracht, damit ich dem Herrn diene.','In dieser Zeit hört man nur selten ein Wort von Gott. Elis Augen werden schwach. Aber die Lampe Gottes ist noch nicht erloschen.','Döserlinge machen alle schläfrig, damit niemand auf Gott hört. Besiege 5 Düsterlinge, dann stell dich dem Schlafnebel beim Haus des Herrn.'],
 hint:'Der Schlafnebel wabert um das Haus des Herrn. Halte deine Ohren offen: Gott redet noch heute!',
 outro:['In der Nacht hat jemand meinen Namen gerufen! Dreimal bin ich zu Eli gelaufen und habe gesagt: „Hier bin ich!“ Aber es war nicht Eli.','Da verstand Eli: Es war der Herr! Beim nächsten Mal sagte ich: „Rede, denn dein Diener hört.“ Und Gott sprach zu mir.','Hier ist ein Teil der Schriftrolle. Und diese Tempellampe brennt immer noch hell. Sie möchte mit dir kommen und deinen Weg erleuchten!'],
 post:'Gott redet noch heute durch sein Wort. Sei bereit zu sagen: „Rede, Herr, ich höre!“',
 side:{name:'Hanna',what:'Wollknäuel',ask:'Ich bin Hanna, Samuels Mutter. Jedes Jahr nähe ich ihm ein neues kleines Gewand. Aber auf dem Weg nach Silo habe ich 3 Wollknäuel verloren! Findest du sie?',thanks:'Danke! Um diesen Jungen habe ich gebetet, und der Herr hat mir gegeben, was ich erbeten habe. Nimm das!'},
 flav:[{name:'Eli',lines:['Als Hanna so innig betete, dass sich nur ihre Lippen bewegten, habe ich es zuerst nicht verstanden. Dann habe ich ihr gesagt: „Geh in Frieden. Gott gebe dir, worum du gebeten hast.“']},{name:'Elkana',lines:['Ich bin Elkana, Samuels Vater. Jedes Jahr zieht unsere Familie hinauf nach Silo, um den Herrn anzubeten.']}],
 verse:{t:'Rede, Herr, denn dein Diener hört.',r:'1. Samuel 3,9-10'}},
25:{name:'Salomos Tempel',book:'1. Könige 3 · 6–8 · 10',foe:{name:'Wirrling',pl:'Wirrlinge',what:'Schatten der Torheit'},foes:[{name:'Wirrling'},{name:'Rätsellicht'},{name:'Torheitstropfen'}],
 boss:{name:'Rätsel-Dunkel',where:'im Tempelvorhof'},guide:{name:'Salomo'},
 intro:['Willkommen in Jerusalem! Ich bin Salomo, der Sohn von König David. Als ich König wurde, fühlte ich mich wie ein kleines Kind, das nicht weiß, was es tun soll.','Gott sagte im Traum zu mir: „Bitte, was ich dir geben soll.“ Ich bat um ein hörendes Herz, damit ich sein Volk gut führen kann.','Gott schenkte mir Weisheit, und noch viel mehr! Jetzt bauen wir dem Herrn einen Tempel, mit Zedernholz aus dem Libanon und viel Gold.','Wirrlinge verbreiten überall dumme Ideen. Besiege 6 Düsterlinge, dann stell dich dem Rätsel-Dunkel im Tempelvorhof.'],
 hint:'Das Rätsel-Dunkel versteckt sich im Tempelvorhof hinter seinen Rätseln. Wahre Weisheit kommt von Gott!',
 outro:['Der Tempel ist fertig! Als die Priester die Bundeslade hineintrugen, erfüllte eine Wolke das Haus. Es war die Herrlichkeit des Herrn!','Später kam die Königin von Saba von weit her, um mich mit schweren Fragen zu prüfen. Gott half mir, jede zu beantworten, und sie lobte den Herrn.','Hier ist ein Teil der Schriftrolle. Und dieser Affe ist mit meinen Schiffen voller Gold und Silber gekommen. Er möchte mit dir reisen!'],
 post:'Wenn du Weisheit brauchst, bitte Gott darum. Er schenkt sie gern!',
 side:{name:'Baumeister aus Tyrus',what:'Zedernstämme',ask:'Ich bin ein Baumeister aus Tyrus. König Hiram hat Zedernstämme aus dem Libanon für den Tempel geschickt, aber 4 davon sind weggerollt! Findest du sie?',thanks:'Danke! Jeder Stein wurde schon im Steinbruch fertig gemacht, darum hörte man beim Tempelbau keinen Hammer. Nimm das!'},
 flav:[{name:'Mutter mit Baby',lines:['Eine andere Frau sagte, mein Baby gehöre ihr! Das weise Urteil von König Salomo zeigte, wer die echte Mutter war. Mein Baby ist sicher bei mir!']},{name:'Königin von Saba',lines:['Ich habe nicht geglaubt, was man über Salomos Weisheit erzählte, bis ich es selbst gesehen habe. Nicht einmal die Hälfte hatte man mir gesagt!']}],
 verse:{t:'Gib deinem Diener ein hörendes Herz, damit er dein Volk richten kann.',r:'1. Könige 3,9'}},
26:{name:'Am Jordan',book:'Matthäus 3–4',foe:{name:'Flüsterling',pl:'Flüsterlinge',what:'Schatten der Versuchung'},foes:[{name:'Flüsterling'},{name:'Abkürzungswicht'},{name:'Hungertropfen'}],
 boss:{name:'Dunkel der Versuchung',where:'am Rand der Wüste'},guide:{name:'Johannes der Täufer'},
 intro:['Willkommen am Jordan! Ich bin Johannes. Ich trage Kleider aus Kamelhaar und esse Heuschrecken und wilden Honig.','Ich sage allen: „Kehrt um, denn das Himmelreich ist nahe!“ Die Leute kommen, bekennen ihre Sünden, und ich taufe sie im Fluss.','Dann kam Jesus, um sich taufen zu lassen. Als er aus dem Wasser stieg, öffnete sich der Himmel, und der Geist Gottes kam wie eine Taube auf ihn herab. Eine Stimme sagte: „Das ist mein geliebter Sohn!“','Flüsterlinge verdrehen Gottes Worte, um Menschen zu täuschen. Besiege 6 Düsterlinge, dann stell dich dem Dunkel der Versuchung am Rand der Wüste.'],
 hint:'Das Dunkel der Versuchung wartet am Rand der Wüste. Antworte wie Jesus: „Es steht geschrieben!“',
 outro:['Nach seiner Taufe ging Jesus in die Wüste und fastete 40 Tage und 40 Nächte. Dann kam der Teufel und versuchte ihn dreimal.','Jedes Mal antwortete Jesus mit Gottes Wort: „Es steht geschrieben!“ Da verließ ihn der Teufel, und Engel kamen und dienten ihm.','Hier ist ein Teil der Schriftrolle. Und dieser Schwan gleitet den Fluss entlang. Er möchte mit dir kommen!'],
 post:'Wenn du versucht wirst, denk an Gottes Wort. Es ist stärker als jede Lüge!',
 side:{name:'Andreas',what:'Töpfe mit wildem Honig',ask:'Ich bin Andreas, einer von Johannes’ Jüngern. Johannes isst Heuschrecken und wilden Honig, und ich habe versprochen, 3 Töpfe Honig fürs Abendessen zu finden. Hilfst du mir?',thanks:'Danke! Eines Tages zeigte Johannes auf Jesus und sagte: „Seht, das Lamm Gottes!“ Ich will ihm folgen! Nimm das.'},
 flav:[{name:'Zöllner',lines:['Ich kam, um mich taufen zu lassen, und fragte Johannes, was ich tun soll. Er sagte: „Verlangt nicht mehr Geld, als festgesetzt ist.“']},{name:'Soldat',lines:['Johannes sagte zu uns Soldaten: „Tut niemandem Gewalt an, beschuldigt niemanden zu Unrecht und seid mit eurem Lohn zufrieden.“']}],
 verse:{t:'Der Mensch lebt nicht vom Brot allein, sondern von jedem Wort, das aus dem Mund Gottes kommt.',r:'Matthäus 4,4'}},
27:{name:'Kana',book:'Johannes 2',foe:{name:'Mangling',pl:'Manglinge',what:'Schatten des „Nicht genug“'},foes:[{name:'Mangling'},{name:'Murrwicht'},{name:'Trockentropfen'}],
 boss:{name:'Dunkel der Leere',where:'beim Hochzeitshaus'},guide:{name:'Maria'},
 intro:['Schalom! Ich bin Maria, die Mutter von Jesus. Wir sind auf einer Hochzeit hier in Kana in Galiläa. Jesus und seine Jünger sind auch eingeladen!','Ein Hochzeitsfest dauert mehrere Tage, mit Musik, Essen und Tanz. Aber oh nein, der Wein ist ausgegangen! Das ist der Familie bestimmt sehr peinlich.','Ich habe zu Jesus gesagt: „Sie haben keinen Wein mehr.“ Dann habe ich zu den Dienern gesagt: „Was er euch sagt, das tut!“','Manglinge flüstern: „Es wird nie genug sein!“ Besiege 5 Düsterlinge, dann stell dich dem Dunkel der Leere beim Hochzeitshaus.'],
 hint:'Das Dunkel der Leere lauert beim Hochzeitshaus. Vertrau Jesus und tu, was er dir sagt!',
 outro:['Jesus sagte zu den Dienern: „Füllt die Krüge mit Wasser.“ Sie füllten sechs große Steinkrüge bis zum Rand.','Dann sagte er: „Schöpft jetzt davon und bringt es dem Speisemeister.“ Das Wasser war zu Wein geworden, zum besten Wein von allen! Das war das erste Zeichen von Jesus, und seine Jünger glaubten an ihn.','Hier ist ein Teil der Schriftrolle. Und einer der Diener möchte dir diesen kleinen Wasserkrug schenken. Er wird dich auf deiner Reise erfrischen!'],
 post:'Tu, was Jesus dir sagt. Er kann mehr, als du dir vorstellen kannst!',
 side:{name:'Hochzeitsdiener',what:'Wassereimer',ask:'Ich bin ein Diener auf der Hochzeit. Irgendwie habe ich das Gefühl, dass wir heute viel Wasser brauchen! Findest du 3 Eimer für mich?',thanks:'Danke! Maria hat gesagt: „Was er euch sagt, das tut!“, und ich will bereit sein. Nimm das.'},
 flav:[{name:'Speisemeister',lines:['Jeder schenkt zuerst den guten Wein aus. Aber dieser Wein ist der beste von allen! Wo kommt er nur her?']},{name:'Natanael',lines:['Ich bin Natanael, und ich komme aus Kana! Ich habe einmal gefragt: „Kann aus Nazaret etwas Gutes kommen?“ Jetzt kenne ich die Antwort!']}],
 verse:{t:'Was er euch sagt, das tut!',r:'Johannes 2,5'}},
28:{name:'Betanien',book:'Johannes 11',foe:{name:'Kummerling',pl:'Kummerlinge',what:'Schatten der Hoffnungslosigkeit'},foes:[{name:'Kummerling'},{name:'Tränenlicht'},{name:'Steingroll'}],
 boss:{name:'Dunkel der Trauer',where:'beim Grab des Lazarus'},guide:{name:'Marta'},
 intro:['Willkommen in Betanien. Ich bin Marta. Meine Schwester Maria, mein Bruder Lazarus und ich lieben Jesus, und Jesus liebt uns.','Lazarus wurde sehr krank. Wir haben Jesus eine Nachricht geschickt: „Herr, der, den du lieb hast, ist krank.“ Aber Jesus blieb noch zwei Tage dort, wo er war.','Jetzt ist Lazarus gestorben. Er liegt schon seit vier Tagen im Grab. Unsere Freunde weinen mit uns, und mein Herz ist so schwer.','Kummerlinge flüstern: „Es ist zu spät. Es gibt keine Hoffnung.“ Besiege 6 Düsterlinge, dann stell dich dem Dunkel der Trauer beim Grab des Lazarus.'],
 hint:'Das Dunkel der Trauer sitzt beim Grab. Aber Jesus ist die Auferstehung und das Leben!',
 outro:['Jesus ist gekommen! Er sagte: „Ich bin die Auferstehung und das Leben.“ Ich antwortete: „Ja, Herr. Ich glaube, dass du der Christus bist, der Sohn Gottes.“','Jesus weinte mit uns. Dann rollten sie den Stein weg, und Jesus rief laut: „Lazarus, komm heraus!“ Und Lazarus kam aus dem Grab, lebendig!','Hier ist ein Teil der Schriftrolle. Und dieses kleine Feigenhörnchen aus unserem Garten möchte mit dir kommen!'],
 post:'Jesus ist traurig mit uns, wenn wir traurig sind. Und er hat sogar Macht über den Tod!',
 side:{name:'Maria aus Betanien',what:'Brote',ask:'Ich bin Maria, Martas Schwester. So viele Freunde sind aus Jerusalem gekommen, um uns zu trösten! Marta möchte ihnen allen etwas zu essen geben. Findest du 4 Brote?',thanks:'Danke! Als Jesus kam, fiel ich ihm zu Füßen und weinte. Er sah mich weinen, und er weinte auch. Nimm das.'},
 flav:[{name:'Lazarus',lines:['Ich lag vier Tage im Grab. Dann hörte ich die Stimme von Jesus: „Lazarus, komm heraus!“ Und ich kam heraus, noch in Grabtücher gewickelt!']},{name:'Freund aus Jerusalem',lines:['Als wir Jesus weinen sahen, sagten wir: „Seht, wie lieb er ihn hatte!“']}],
 verse:{t:'Ich bin die Auferstehung und das Leben. Wer an mich glaubt, der wird leben, auch wenn er stirbt.',r:'Johannes 11,25'}}
});
